// Pure deterministic game rules, shared by the browser and optional room server.
export const WORLD={w:25,h:20,spawn:{x:3,y:11},ticket:{x:3,y:6},gate:{x:8,y:8},gatePad:{x:5,y:9},powerPad:{x:12,y:10},tram:{x:13.6,y:4.1},duration:90,speed:3.2};
export const LANDMARKS=[{id:'garden',x:20,y:7,name:'Lantern Garden',memory:'In the lantern garden, every light is a wish someone came back for.'},{id:'lookout',x:21,y:15,name:'Tomorrow Lookout',memory:'From the lookout, the city stretches beyond the rain. There is more than one way home.'},{id:'clock',x:4,y:17,name:'The Waiting Clock',memory:'The clock has stopped at midnight. Someone scratched: “We still have tomorrow.”'}];
export const BUILDINGS=[{x:1,y:1,w:3,h:2,z:84,color:'#bd8b70',name:'MORI BOOKS'},{x:5,y:1,w:2,h:3,z:110,color:'#678776',name:'NO. 04'},{x:1,y:8,w:1.2,h:2,z:46,color:'#b0a47f',name:'CAFÉ'},{x:10,y:1,w:2,h:2,z:66,color:'#9c8fbd',name:'STATION'},{x:14.5,y:8,w:1.5,h:3,z:80,color:'#6d8994',name:'RADIO'},{x:10,y:12,w:3,h:1,z:30,color:'#b69074',name:'FLOWERS'}];
export const CHARACTERS=[{name:'Sudip',color:'#e5f18c'},{name:'Sondor',color:'#9ce0dc'},{name:'Eric',color:'#e9aa8e'},{name:'Abinash',color:'#c1afe8'}];
export const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export const SHARDS=[{id:'lane',x:5.2,y:11.5},{id:'bridge',x:6.4,y:6.2},{id:'station',x:10,y:8.5},{id:'lookout',x:17,y:14},{id:'garden',x:21,y:7.5}];
export function createGame(players=[{id:'solo',name:'Sudip',color:'#e5f18c'}]){return {version:1,time:0,loop:1,echoes:[],recording:[],players:players.map((p,i)=>({...p,x:WORLD.spawn.x+i*.35,y:WORLD.spawn.y,target:null})),ticket:false,gateOpen:false,power:false,won:false,started:false,paused:false,rewinds:0,shards:[],memories:[],message:'',event:0};}
BUILDINGS.push({x:17,y:1,w:3,h:3,z:125,color:'#7d8f9c',name:'THE GRAND'},{x:21,y:3,w:2,h:2,z:68,color:'#b39981',name:'LANTERN'},{x:18,y:10,w:2,h:2,z:93,color:'#8b9e8b',name:'RECORDS'},{x:12,y:16,w:3,h:2,z:100,color:'#9b8b9f',name:'TOMORROW'},{x:1,y:14,w:2,h:2,z:58,color:'#b4917c',name:'ATELIER'});
export function blocked(x,y,gateOpen){if(x<.5||x>WORLD.w-.5||y<.5||y>WORLD.h-.5)return true;if(Math.abs(x-8)<.3&&!(gateOpen&&y>7&&y<9))return true;return BUILDINGS.some(b=>x>b.x-.15&&x<b.x+b.w+.15&&y>b.y-.15&&y<b.y+b.h+.15);}
export function echoAt(e,t){const samples=e.frames;if(!samples.length)return null;let lo=0,hi=samples.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(samples[mid].t<=t)lo=mid;else hi=mid-1;}const a=samples[lo],b=samples[Math.min(lo+1,samples.length-1)];const ratio=b.t>a.t?Math.max(0,Math.min(1,(t-a.t)/(b.t-a.t))):0;return {...e,x:a.x+(b.x-a.x)*ratio,y:a.y+(b.y-a.y)*ratio,holding:t>=samples.at(-1).t};}
export function actors(g){return [...g.players,...g.echoes.map(e=>echoAt(e,g.time)).filter(Boolean)];}
export function refresh(g){const all=actors(g);g.gateOpen=all.some(a=>dist(a,WORLD.gatePad)<.7);g.power=all.some(a=>dist(a,WORLD.powerPad)<.7);}
export function collectLights(g){g.shards??=[];for(const light of SHARDS){if(!g.shards.includes(light.id)&&g.players.some(p=>dist(p,light)<.65)){g.shards.push(light.id);tell(g,`Memory light ${g.shards.length}/5. The city remembers you.`);}}}
export function tell(g,message){g.message=message;g.event++;}
export function rewind(g){if(g.won||!g.started)return false;if(g.time<.6){tell(g,'Take a few steps first. Your echo needs a memory.');return false;}for(const p of g.players){const frames=g.recording.filter(f=>f.id===p.id).map(({t,x,y})=>({t,x,y}));frames.push({t:g.time,x:p.x,y:p.y});g.echoes.push({id:`echo-${g.loop}-${p.id}`,name:p.name,color:p.color,loop:g.loop,frames});}g.echoes=g.echoes.slice(-12);g.loop++;g.rewinds++;g.time=0;g.recording=[];for(const p of g.players){p.x=WORLD.spawn.x;p.y=WORLD.spawn.y;p.target=null;}refresh(g);tell(g,'Yesterday is on your side. Your echo repeats that route, then holds its last position.');return true;}
export function interact(g,id){if(!g.started||g.won||g.paused)return;const p=g.players.find(p=>p.id===id);if(!p)return;if(dist(p,WORLD.ticket)<1.2){if(!g.ticket){g.ticket=true;g.memories.push('A ticket marked 00:00. Someone has been waiting for you.');tell(g,'Ticket recovered. Memories survive every rewind. Now stand on the amber gate pad.');}else tell(g,'The ticket is safe. Even time cannot take it back.');}
 else if(dist(p,WORLD.tram)<1.6){if(!g.ticket)tell(g,'The conductor needs your ticket. Find the glowing kiosk across the canal.');else if(!g.power)tell(g,'No power. Someone—or an echo—must stay on the blue generator pad.');else if(g.time>85)tell(g,'The last tram has departed. Rewind and reach it before 00:05.');else{g.won=true;g.memories.push('The conductor is you, from a tomorrow you finally reached.');tell(g,'You made tomorrow possible.');}}
 else if(dist(p,WORLD.gatePad)<1)tell(g,'You are holding the gate open. Press R here: your echo will take this job next loop.');
 else if(dist(p,WORLD.powerPad)<1)tell(g,'Power restored while you stay here. Press R to leave an echo on this pad.');
 else {const place=LANDMARKS.find(l=>dist(p,l)<1.3);if(place){if(!g.memories.includes(place.memory))g.memories.push(place.memory);tell(g,place.memory);}else tell(g,'Find the ticket kiosk, glowing pads, tram, or a marked landmark. Walk close and press E.');}}
export function tick(g,dt,inputs={}){if(!g.started||g.paused||g.won)return;dt=Math.min(.1,Math.max(0,dt));g.time+=dt;refresh(g);for(const p of g.players){const input=inputs[p.id]||{};let dx=Number(input.dx)||0,dy=Number(input.dy)||0;if(Math.abs(dx)+Math.abs(dy)>.01)p.target=null;else if(p.target){dx=p.target.x-p.x;dy=p.target.y-p.y;if(Math.hypot(dx,dy)<.15){p.target=null;dx=dy=0;}}const len=Math.hypot(dx,dy);if(len){dx=dx/len*WORLD.speed*dt;dy=dy/len*WORLD.speed*dt;const x=p.x+dx,y=p.y+dy;if(!blocked(x,p.y,g.gateOpen))p.x=x;if(!blocked(p.x,y,g.gateOpen))p.y=y;}if(!g.recording.length||g.time-(g.recording.at(-1)?.t??0)>=.075)for(const q of g.players)g.recording.push({id:q.id,t:g.time,x:q.x,y:q.y});}refresh(g);collectLights(g);if(g.time>=WORLD.duration)rewind(g);}
export function exportSave(g){return JSON.stringify({...g,started:false,paused:false,recording:[]});}
export function importSave(text){const g=JSON.parse(text);if(g.version!==1||!Array.isArray(g.players)||!Array.isArray(g.echoes)||!Number.isFinite(g.time)||!Number.isInteger(g.loop)||g.players.length<1||g.players.length>4||g.echoes.length>12)throw new Error('Invalid save');for(const p of g.players)if(!Number.isFinite(p.x)||!Number.isFinite(p.y))throw new Error('Invalid position');for(const e of g.echoes)if(!Array.isArray(e.frames)||e.frames.length>6000||e.frames.some(f=>!Number.isFinite(f.t)||!Number.isFinite(f.x)||!Number.isFinite(f.y)))throw new Error('Invalid echo');g.shards=Array.isArray(g.shards)?[...new Set(g.shards.filter(id=>SHARDS.some(s=>s.id===id)))]:[];return g;}
